--
-- Point ledger. Rows with an ExpiresAt in the past are excluded from the tally
-- by calculate_tallies, so the dbo.UserTallies rows this produces are smaller
-- than the sum of the amounts here. UserTallies is not seeded directly: the
-- UserPoints_UserTallies triggers build it from these rows.
--

ON CONFLICT ("UserPointUUID") DO UPDATE SET
    "Description" = EXCLUDED."Description",
    "Reason" = EXCLUDED."Reason",
    "Details" = EXCLUDED."Details",
    "Amount" = EXCLUDED."Amount",
    "ExpiresAt" = EXCLUDED."ExpiresAt",
    "UpdatedBy" = 'seed';
